bleau d&#39;&#233;quipement des PNJ&lt;/a&gt; ou le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#TABLERICHESSEPJPARNIVEAU&quot; title=&quot;Les rencontres&quot;&gt;tableau des richesses par niveau&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TABLERICHESSEDEPARTPJ&quot; href=&quot;#TABLERICHESSEDEPARTPJ&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;center&gt;
